      slices.forEach((s, j) => { if (s.at > 0 && s.inset >= p.rim && (edge < 0 || s.at < slices[edge].at)) edge = j; });
      // Slices under the edge slice take the color out to a little past its edge, not across their
      // whole hidden middle, so no hairline gap in the planes above can show it.
      const under = edge < 0 ? null : rimPath(outlines[p.part].polys, slices[edge].inset + 1.5);
