    for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) edges.push([poly[j][0], poly[j][1], poly[i][0], poly[i][1]]);
  const cell = 2, cx = (x) => Math.floor((x - x0) / cell), cy = (y) => Math.floor((y - y0) / cell);
  const cols = cx(x0 + nx * step) + 1, rows = cy(y0 + ny * step) + 1;
